// commonMain/kotlin/ui/navigation/RootNavHost.kt
@Composable
fun RootNavHost(
    appState: AppStateHolder
) {
    val isAuthenticated by appState.isAuthenticated.collectAsState()

    val navController = rememberNavController()

    if (isAuthenticated) {
        MainNavHost(navController)
